def count_issued(apps, schema_editor):
    """Published companies: parts on sale or still collecting count fully; others count what was sold."""
    Project = apps.get_model("projects", "Project")
    for p in Project.objects.filter(kind="company").exclude(status__in=["draft", "submitted", "changes", "rejected"]):
        offered = int(p.target_amount // p.share_price) if p.share_price else 0
        p.shares_issued = offered if (p.status in ("funding", "funded") or p.offering_open) else p.shares_sold
        p.save(update_fields=["shares_issued"])


